      kind: "entity-used";
      /** The id of the NPC or prop the player used. */
      entityId: string;
      /** The item id the player used on it, or "" for a bare use. */
      item: string;
      /** Which control the player used, or absent where the world does not say. */
      button?: "primary" | "secondary" | "use";
